(function(H){
'use strict';
const $=id=>document.getElementById(id),app=$('app'),dialog=$('modal'),saves=new H.SaveAdapter();
let engine=null,seq=0,busy=false,screen='start',selected=H.products[0].id,filter='全部',sort='default',focusReturn=null,tradeMode='buy',tradeId=null,lastAction=0,dialogKind=null,enteredByNext=false;
const sr=saves.loadSettings();let settings=sr.settings,load=saves.load(),storageStatus=load.ok?(load.state?'已有本地存档':load.notice||'暂无存档'): '原档已隔离：'+load.error;
let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('homeyear.favorites')||'[]'));}catch(e){}
if(H.Art&&H.Art.mount)H.Art.mount(document);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+(settings.numberFormat==='compact'&&Math.abs(n)>=1000000?(n/1000000).toFixed(2)+'万':(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}));
const icon=id=>H.Art?H.Art.icon(id,'product-icon'):'<span class="avatar">'+esc(H.holding(id).icon)+'</span>';
const scene=(kind,opts)=>H.Art?H.Art.scene(kind,opts):'<div class="avatar">⌂</div>';
const btn=(text,action,extra='')=>`<button data-action="${action}" ${extra}>${text}</button>`;
const SEASON={'冬':'winter','春':'spring','夏':'summer','秋':'autumn'},TONE_CN={dusk:'黄昏',morning:'清晨',day:'午后',evening:'入夜',golden:'金色时刻',bluehour:'蓝调时刻'},CAT={'生活':'life','电子':'tech','贵重':'lux','季节':'season','应急':'aid'};
const climateOf=s=>s.macro>1.04?'偏热':s.macro<.96?'偏冷':'平稳';
// Public progress to the next house: identical to the UI progress bar (cash / due), 1 once the top house is owned.
function homeGoal(s){const owned=H.houses.findIndex(h=>h.id===s.house),goal=H.houses[Math.min(owned+1,4)],due=H.housePrice(s,goal)-H.houseValue(s);return {owned,goal,due,progress:due>0?Math.max(0,Math.min(1,s.cash/due)):1};}
// Visual phase = the music director's logical target (same hysteresis: development at p≥0.90, back to early below 0.80),
// computed by a UI-owned director instance from the same public scene payload. Never reads audio cues or timing.
const director=H.AudioDirector&&H.AudioDirector.createDirector?H.AudioDirector.createDirector():(()=>{let t='menu';return {request(sc){t=sc.screen!=='game'?'menu':sc.status==='ended'?(sc.house?'ending-home':'ending-rent'):sc.week>=45?'sprint':(sc.week>=18||sc.house)?'development':sc.progress>=(t==='development'?.8:.9)?'development':'early';return t;}};})();
// The year-end storybook is not a transient dialog: the ending cue only ever plays behind it, so it must not be
// pushed through the 2.5 kHz / -4 dB dialog mix. Trade / houses / settings / confirm keep the duck snapshot.
function scenePayload(s){return {screen,week:s?s.week:null,status:s?s.status:null,house:s?s.house:null,progress:s?+homeGoal(s).progress.toFixed(4):null,season:s?SEASON[s.season]:null,climate:s?{'偏热':'hot','偏冷':'cold','平稳':'steady'}[climateOf(s)]:null,dialogOpen:dialog.open&&dialogKind!=='result',dialog:dialog.open?dialogKind:null};}
let visual='menu';
function phaseOf(s){visual=director.request(scenePayload(s&&screen==='game'?s:null));return visual;}
function chart(values,cls='spark',o={}){const all=o.avg?values.concat(o.avg):values,min=Math.min(...all),span=Math.max(...all)-min||1,X=i=>+(i*300/Math.max(1,values.length-1)).toFixed(1),Y=v=>+(75-(v-min)*68/span).toFixed(1),pts=values.map((v,i)=>`${X(i)},${Y(v)}`).join(' ');let extra='';if(o.grid)extra+=`<path d="M0 7H300M0 24H300M0 41H300M0 58H300M0 75H300" stroke="currentColor" stroke-opacity=".12" stroke-width="1" vector-effect="non-scaling-stroke"/>`;if(o.avg)extra+=`<path d="M0 ${Y(o.avg)}H300" stroke="#b88a4a" stroke-width="1.5" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/>`;if(o.marks)for(const m of o.marks)extra+=m.type==='line'?`<path d="M${X(m.i)} 0V80" stroke="${m.color}" stroke-width="1.5" stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/>`:`<circle cx="${X(m.i)}" cy="${Y(values[m.i])}" r="3.5" fill="${m.color}" stroke="#fffaf0" stroke-width="1.5" vector-effect="non-scaling-stroke"/>`;return `<svg class="${cls}" viewBox="0 0 300 80" preserveAspectRatio="none" role="img" aria-label="${o.label||'历史曲线，非未来预测'}">${extra}<path d="M0 80L${pts.replace(/ /g,'L')}L300 80Z" fill="url(#hy-${o.up?'chart-up':'chart'})" stroke="none"/><polyline fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke" points="${pts}"/></svg>`;}
function toast(text,error=false){while($('toasts').children.length>=2)$('toasts').firstElementChild.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=text;$('toasts').append(el);setTimeout(()=>el.remove(),4500);}
let modalOrigin=null;
function modal(title,html,kind='info'){if(!dialog.open){focusReturn=document.activeElement;modalOrigin={warehouse:captureWarehouse(),id:focusReturn.id,testid:focusReturn.dataset.testid,action:focusReturn.dataset.action,product:focusReturn.dataset.id};dialog.showModal();}dialogKind=kind;dialog.dataset.kind=kind;dialog.innerHTML=`<header class="dialog-head"><h2 id="modal-title">${title}</h2>${btn('×','close','aria-label="关闭"')}</header><div class="dialog-body">${html}</div>`;requestAnimationFrame(()=>{const e=dialog.querySelector('input:not([type=file]),button,select');if(e)e.focus();});syncScene();}
function close(){dialog.close();tradeId=null;dialogKind=null;const origin=modalOrigin;let target=origin&&origin.warehouse.key?warehouseTarget(origin.warehouse):focusReturn&&focusReturn.isConnected&&!focusReturn.disabled?focusReturn:null;if(!target&&origin){if(origin.id)target=$(origin.id);if(!target&&origin.testid)target=app.querySelector(`[data-testid="${origin.testid}"]`);if(!target&&origin.action)target=app.querySelector(`[data-action="${origin.action}"]${origin.product?'[data-id="'+origin.product+'"]':''}`);}if(!target||target.disabled)target=$('warehouse-title')||app.querySelector('[data-testid=new-game]');if(target)target.focus({preventScroll:true});else {app.tabIndex=-1;app.focus({preventScroll:true});}if(origin&&origin.warehouse.key){const list=app.querySelector('.warehouse-list');if(list)list.scrollTop=origin.warehouse.scroll;}syncScene();}
let confirmFn=null;
function confirmBox(text,fn){confirmFn=fn;modal('请确认',`<p>${esc(text)}</p><div class="row">${btn('取消','close')}${btn('确认','confirm','class="primary" data-testid="confirm-yes"')}</div>`,'confirm');}
function wire(){engine.onCommit=s=>{if(!settings.autoSave){storageStatus='自动存档已关闭 · 当前进度可能未保存';return;}const r=saves.save(s);storageStatus=r.ok?'已自动保存':'未保存：'+r.error;if(!r.ok)throw Error(r.error);};}
function applySettings(){document.body.dataset.animation=settings.animation;H.Audio.configure(settings);if(!settings.music&&!settings.sound&&typeof audioPrompt==='function')audioPrompt(false);}
const motion=()=>settings.animation==='normal'&&!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);

// ---- scene slots: big illustrations are parsed once per key and their DOM node is reused across re-renders ----
const slots=new Map();
const slot=(name,kind,opts={})=>`<div class="scene-slot slot-${name}" data-slot="${name}" data-kind="${kind}" data-opts="${esc(JSON.stringify(opts))}"></div>`;
function mountSlots(root){for(const el of root.querySelectorAll('[data-slot]')){const name=el.dataset.slot,key=el.dataset.kind+'|'+el.dataset.opts;let c=slots.get(name);if(!c||c.key!==key){const node=document.createElement('div');node.className='scene-host';node.innerHTML=scene(el.dataset.kind,JSON.parse(el.dataset.opts));c={key,node,built:(c?c.built:0)+1};slots.set(name,c);}el.append(c.node);}}

// ---- public scene for audio + body phase/season (public values only; never RNG, trends or hidden events) ----
let lastScene=null,lastSceneKey='';
function syncScene(){const s=engine&&screen==='game'?engine.snapshot():null,phase=phaseOf(s),season=s?SEASON[s.season]:null;document.body.dataset.phase=phase;document.body.dataset.season=season||'none';const sc=scenePayload(s);const key=JSON.stringify(sc);if(key===lastSceneKey)return;lastSceneKey=key;lastScene=Object.freeze(sc);try{if(H.Audio&&typeof H.Audio.setScene==='function')H.Audio.setScene({...sc});}catch(e){}}

// ---- house celebration: door opens, warm light, key flash, ≤120 confetti that stop after 2.5s ----
const fx={celebrating:false,confetti:false,raf:0,timer:0,el:null,frames:0};
function endCelebration(){cancelAnimationFrame(fx.raf);clearTimeout(fx.timer);fx.raf=0;fx.confetti=false;if(fx.el){try{if(fx.el.hidePopover&&fx.el.matches(':popover-open'))fx.el.hidePopover();}catch(e){}fx.el.remove();}fx.el=null;fx.celebrating=false;}
function confetti(canvas){const w=canvas.width=innerWidth,h=canvas.height=innerHeight,ctx=canvas.getContext('2d');if(!ctx)return;const cols=['#e2b24a','#c95a48','#6f9a84','#f6e4c8','#5f8fb4','#b88a4a'],ps=[];let seed=7;const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647;for(let i=0;i<120;i++)ps.push({x:w/2+(rnd()-.5)*w*.3,y:h*.42,vx:(rnd()-.5)*11,vy:-4-rnd()*9,r:rnd()*6.3,s:4+rnd()*5,c:cols[i%cols.length]});const t0=performance.now();fx.confetti=true;const step=now=>{const t=now-t0;fx.frames++;if(t>2500||document.hidden||!fx.el){ctx.clearRect(0,0,w,h);fx.confetti=false;fx.raf=0;return;}ctx.clearRect(0,0,w,h);ctx.globalAlpha=Math.min(1,(2500-t)/600);for(const p of ps){p.vy+=.28;p.vx*=.99;p.x+=p.vx;p.y+=p.vy;p.r+=.12;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.r);ctx.fillStyle=p.c;ctx.fillRect(-p.s/2,-p.s/4,p.s,p.s/2);ctx.restore();}fx.raf=requestAnimationFrame(step);};fx.raf=requestAnimationFrame(step);}
function celebrate(id){endCelebration();const j=H.houses.findIndex(h=>h.id===id);if(j<0)return;const h=H.houses[j],s=engine&&engine.snapshot(),moving=motion(),el=document.createElement('div');el.className='celebration'+(moving?'':' still');el.setAttribute('aria-hidden','true');el.innerHTML=`<div class="celebration-stage"><div class="celebration-art">${scene('house-'+j,{phase:'ending-home',season:s?SEASON[s.season]:null})}<div class="door" ><i class="door-leaf"></i></div><div class="key-flash">${H.Art?H.Art.icon('seal'):''}</div></div><p class="celebration-title">钥匙到手了</p><p class="celebration-sub">${esc(h.name)} · ${esc(h.district)} · 从今天起，推开的是自己家的门。</p></div>${moving?'<canvas class="confetti"></canvas>':''}`;el.setAttribute('popover','manual');document.body.append(el);try{if(el.showPopover)el.showPopover();}catch(e){}fx.el=el;fx.celebrating=true;if(moving)confetti(el.querySelector('canvas'));fx.timer=setTimeout(endCelebration,moving?3200:2200);}

// ---- start page parallax: pointer driven, one rAF per move, ≤8 CSS px, off when motion is reduced ----
let parallaxRaf=0,parallaxXY=[0,0];
document.addEventListener('pointermove',e=>{if(screen!=='start'||e.pointerType==='touch'||!motion()||document.hidden)return;parallaxXY=[e.clientX/innerWidth-.5,e.clientY/innerHeight-.5];if(parallaxRaf)return;parallaxRaf=requestAnimationFrame(()=>{parallaxRaf=0;const svg=app.querySelector('.art-city');if(!svg)return;const k=svg.getBoundingClientRect().width/1600||1;[['.hy-far',2.5],['.hy-mid',5],['.hy-near',8]].forEach(([sel,px])=>{const g=svg.querySelector(sel);if(g)g.style.transform=`translate(${(-parallaxXY[0]*px/k).toFixed(2)}px,${(-parallaxXY[1]*px*.5/k).toFixed(2)}px)`;});});});
document.addEventListener('visibilitychange',()=>{if(document.hidden){endCelebration();if(parallaxRaf){cancelAnimationFrame(parallaxRaf);parallaxRaf=0;}}});
// Audio could not start (resume rejected or not running after 1s): show a clickable prompt instead of failing silently.
// The global click handler already calls H.Audio.unlock() inside the trusted gesture; the prompt removes itself once running.
function audioPrompt(show){let el=$('audio-enable');if(!show){if(el)el.remove();return;}if(el)return;el=document.createElement('button');el.id='audio-enable';el.className='audio-enable';el.dataset.action='audio-enable';el.dataset.testid='audio-enable';el.textContent='🔈 点击启用声音';el.setAttribute('aria-label','声音未能启动，点击启用声音');document.body.append(el);}
function audioCheck(){setTimeout(()=>{const st=H.Audio.status();if(st.state==='running'||!(settings.music||settings.sound))audioPrompt(false);},350);}
window.addEventListener('homeyear:audio-blocked',()=>{if(settings.music||settings.sound)audioPrompt(true);});

function act(type,id,qty){if(busy||Date.now()-lastAction<220)return false;busy=true;lastAction=Date.now();try{const s=engine.visible(),r=engine.dispatch({type,id,qty,revision:s.revision,token:'formal-ui-'+(++seq)});if(!r.ok){toast(r.error,true);H.Audio.play('error');return false;}H.Audio.play(type==='house'?'house':type==='next'?'next':type==='buy'?'buy':type==='sell'?'sell':'click');const sold=type==='sell'?'已卖出'+H.holding(id).name+' × '+qty+'，净回款 '+money(H.channelNet(s,id,qty)):'';toast(r.saveError?(sold||'操作成功')+'，但未保存：'+r.saveError:sold?sold+(!settings.autoSave?' · 自动存档关闭，进度未保存':''):type==='next'?'新的一周，新的机会':type==='house'?'钥匙到手了！这是属于你的家。':'操作完成',!!r.saveError);if(type==='next'){enteredByNext=true;sort='focus';warehouseDrafts.clear();}renderGame();if(type==='house')setTimeout(()=>celebrate(id),0);if(type==='next'){const now=engine.snapshot();if(now.week>=50)toast('含本周还可经营'+(53-now.week)+'周'+(now.week===52?' · 仍可交易，结束须确认':''));if(now.news.length)H.Audio.play('news');const fresh=now.news.find(n=>n.kind==='headline'&&n.fresh&&now.swanLog.some(l=>l.id===n.id&&l.week===now.week));if(fresh){const next=app.querySelector('[data-testid=next-week]');if(next)next.focus({preventScroll:true});majorEvent(fresh.id);}}if(type==='end')result();return true;}finally{busy=false;}}
function localOld(){return load.oldV3 || load.legacy;}
function oldKey(){for(const key of ['homeyear.save.v5','homeyear.save.v4',saves.v3Key,saves.legacyKey,'homeyear.save.v1']){const r=saves.readKey(key);if(r.ok&&r.raw!==null)return key;}return saves.legacyKey;}
function oldConfirm(version){return version===3?H.upgradeConfirm:H.migrationConfirm;}
function start(){screen='start';endCelebration();app.innerHTML=`<section class="start">${slot('city','city',{lamps:true})}<div class="start-copy paper"><div class="brand-line">${H.Art?H.Art.icon('seal','seal'):''}<h1>这一年，安个家</h1></div><p class="muted">从出租屋的一角，到一扇属于自己的门。</p><p>距离拥有自己的家，还有 <strong>52</strong> 周。</p></div><div class="start-form panel paper stack"><small>城市生活 · 轻策略经营</small><h2>你的新生活，从这里开始</h2><label>这一局的种子<input id="seed" data-testid="seed" maxlength="128" value="CITY-${Date.now().toString().slice(-6)}" placeholder="输入种子可重现市场"></label><label>生活节奏<select id="difficulty" data-testid="difficulty">${Object.entries(H.difficulties).map(([id,d])=>`<option value="${id}" ${id==='standard'?'selected':''}>${d.name} · 初始 ${money(d.initialCash)}</option>`).join('')}</select></label>${btn('开始新的一年','new','class="primary" data-testid="new-game"')}${btn('继续我的生活','continue',`data-testid="continue" ${!load.ok||!load.state?'disabled':''}`)}<small>${esc(!load.ok?'继续不可用：'+load.error:!load.state?'继续不可用：还没有本地新档': '存档：第 '+load.state.week+' 周 · '+load.state.seed)}${load.notice?' · '+esc(load.notice):''}</small><div class="row">${btn('玩法与帮助','help')}${btn('设置与存档','settings')}</div><small>${esc(storageStatus)} · 完全离线，无账号</small></div></section>`;mountSlots(app);syncScene();}
function holdingRow(s,id){const p=H.holding(id),legacy=!!p.legacy,m=legacy?s.legacy[id]:s.market[id],i=legacy?s.legacy[id]:s.inventory[id];return {p,legacy,m,i,listed:!legacy&&s.listing.includes(id)};}
function maxBuy(s,p){if(!s.listing.includes(p.id)||p.legacy)return 0;const price=s.market[p.id].price;let n=Math.min(Math.floor(s.cash/price),Math.floor((s.capacity-H.used(s))/p.size));while(n>0&&n*price+H.fee(n*price)>s.cash)n--;return n;}
// UI-only draft state: never part of Engine snapshots or saves.
const warehouseDrafts=new Map();
let resetWarehouse=false;
function clearWarehouseUI(){warehouseDrafts.clear();resetWarehouse=true;}
function submitSale(el,id,q){if(busy)return;const controls=[...document.querySelectorAll(`[data-holding="${id}"] [data-action=quick-sell],[data-holding="${id}"] [data-action=custom-submit]`)].filter(e=>!e.disabled);controls.forEach(e=>e.disabled=true);try{return act('sell',id,q);}finally{controls.forEach(e=>{if(e.isConnected)e.disabled=false;});}}
function salePreview(s,id,raw){
 const row=holdingRow(s,id),q=/^[1-9]\d*$/.test(raw)?Number(raw):0;
 const reason=!Number.isSafeInteger(q)||q<1||q>100000000?'请输入有效正整数（不能含小数、负号或科学记数）':s.status==='ended'?'本年已结束':q>row.i.qty?'持仓不足':'';
 if(reason)return {reason};
 const gross=H.channelGross(s,id,q),fee=H.fee(gross),net=H.channelNet(s,id,q),cost=q===row.i.qty?H.costOf(s,id):Number(BigInt(H.costOf(s,id))*BigInt(q)/BigInt(row.i.qty));
 return {q,gross,fee,net,cost,profit:net-cost,discount:row.m.price*q-gross,reason:''};
}
function saleText(v){return v.reason?`<span class="danger">${esc(v.reason)}</span>`:`${v.q} 件 · 货款 ${money(v.gross)}${v.discount?' · 回收折价 '+money(v.discount):''} · 手续费 ${money(v.fee)} · 净回款 <b>${money(v.net)}</b> · 分摊成本 ${money(v.cost)} · 盈亏 ${money(v.profit)}`;}
function warehouse(s){const used=H.used(s),held=H.heldProducts().filter(p=>H.qtyOf(s,p.id));return `<section class="panel warehouse-panel ledger inventory-panel" data-testid="warehouse"><div class="warehouse-summary"><h3 id="warehouse-title" tabindex="-1">我的仓库</h3><small>${esc(H.warehouses.find(w=>w.id===s.warehouse).name)} · 已占 ${used} / ${s.capacity} · 空余 ${s.capacity-used}</small><div class="progress crate-progress"><i style="width:${used/s.capacity*100}%"></i></div><small>可变现净额 ${money(H.liquidValue(s))}</small>${btn('扩展经营空间','warehouses','data-testid="warehouses"')}<h3>手里的货</h3></div><div class="warehouse-list" data-testid="warehouse-list">${held.map(p=>{const row=holdingRow(s,p.id),draft=warehouseDrafts.get(p.id),net=H.channelNet(s,p.id,row.i.qty),off=s.status==='ended';return `<article class="inventory-card" data-holding="${p.id}"><h3>${esc(p.name)} × ${row.i.qty}</h3><small>占用 ${row.i.qty*p.size} 空间 · ${row.legacy?'已退出 · 冻结参考价回收':row.listed?'本周在售':'未上架 · 回收折价 8%'}</small><small>${row.listed?'成交':'回收'}单价 ${money(H.channelUnit(s,p.id))} · 持仓成本 ${money(H.costOf(s,p.id))}</small><p>卖全部净额 <b>${money(net)}</b> · 浮盈 ${money(net-H.costOf(s,p.id))}</p><div class="sale-buttons">${[1,5,'all'].map(q=>btn(q==='all'?'卖全部':'卖 '+q,'quick-sell',`data-id="${p.id}" data-qty="${q}" data-focus="sell-${p.id}-${q}" ${off||(q===5&&row.i.qty<5)?'disabled':''}`)).join('')}</div><div class="sale-preview" data-quick-preview="${p.id}" aria-live="polite">${saleText(salePreview(s,p.id,String(row.i.qty)))}</div><div class="sale-secondary">${btn('自定义数量','custom-sell',`data-id="${p.id}" data-focus="custom-${p.id}" aria-expanded="${warehouseDrafts.has(p.id)}" ${off?'disabled':''}`)}${btn('查看详情','trade',`data-id="${p.id}" data-mode="sell" data-focus="detail-${p.id}"`)}</div>${warehouseDrafts.has(p.id)?`<div class="inline-sale"><label for="sale-${p.id}">${esc(p.name)} · 整数数量</label><input id="sale-${p.id}" data-sale-input="${p.id}" data-focus="input-${p.id}" inputmode="numeric" autocomplete="off" value="${esc(draft)}"><div data-custom-preview="${p.id}" aria-live="polite">${saleText(salePreview(s,p.id,draft))}</div>${btn('确认卖出','custom-submit',`data-id="${p.id}" data-focus="submit-${p.id}" ${salePreview(s,p.id,draft).reason?'disabled':''}`)}</div>`:''}</article>`;}).join('')||'<p class="muted">仓库还没有货，去街区市场看看。</p>'}</div></section>`;}
function captureWarehouse(){const list=document.querySelector('.warehouse-list'),active=document.activeElement,card=active&&active.closest('[data-holding]');return {scroll:list?list.scrollTop:0,key:active&&active.dataset.focus,action:active&&active.dataset.action,id:card&&card.dataset.holding,ids:[...document.querySelectorAll('[data-holding]')].map(el=>el.dataset.holding)};}
function warehouseTarget(saved){let target=app.querySelector(`[data-focus="${saved.key}"]`);if(target&&!target.disabled)return target;const ids=[...app.querySelectorAll('[data-holding]')].map(el=>el.dataset.holding),at=saved.ids.indexOf(saved.id),same=ids.includes(saved.id),id=same?saved.id:saved.ids.slice(at+1).find(id=>ids.includes(id))||saved.ids.slice(0,at).reverse().find(id=>ids.includes(id));if(!id)return $('warehouse-title');const card=app.querySelector(`[data-holding="${id}"]`);if(same&&saved.action==='custom-submit')target=card.querySelector('[data-sale-input]');else if(saved.action==='trade')target=card.querySelector('[data-action=trade]');else target=card.querySelector('[data-action=quick-sell][data-qty="1"]');return target&&!target.disabled?target:card.querySelector('button:not(:disabled)')||$('warehouse-title');}
function restoreWarehouse(saved){const list=app.querySelector('.warehouse-list');if(!list)return;if(saved.key){const target=warehouseTarget(saved);if(target)target.focus({preventScroll:true});}list.scrollTop=saved.scroll;}
function personalLetter(s){const ns=s.news.filter(n=>n.kind==='personal');return `<section class="personal-letter letter" data-testid="personal-letter">${ns.length?`<details><summary>城市来信 · ${ns.map(n=>esc(n.title)).join(' · ')}</summary><div class="personal-body">${ns.map(n=>`<article class="news news-personal"><p>${esc(n.title)}</p><small>生活事件 · 仅影响现金，不改变商品行情。${esc(H.newsSituation(n))}</small></article>`).join('')}</div></details>`:'<small>城市来信 · 这周没有生活事件。</small>'}</section>`;}
function swanQuote(s,id){const p=H.holding(id),bps=H.changeBps(H.quoteOf(s,id)),qty=H.qtyOf(s,id),listed=s.listing.includes(id);return `<div class="swan-product" data-swan-product="${id}"><p class="${bps>=0?'up':'down'}" title="相对上周成交价">${esc(p.name)} · 本周 ${bps>=0?'+':''}${(bps/100).toFixed(1)}%</p><small>${esc(p.name)} · ${listed?'本周可买':'仅可回收'} · 持有 ${qty} · 当前渠道净额 ${money(qty?H.channelNet(s,id,qty):0)}</small>${btn('查看'+esc(p.name),'trade',`data-id="${id}" data-mode="${listed?'buy':'sell'}"`)}</div>`;}
function majorEvent(id){const s=engine.snapshot(),e=H.events.find(e=>e.id===id&&e.tier==='swan'),log=s.swanLog.find(l=>l.id===id),o=H.swanOrigins[id];if(!e||!log||!o)return;const next=app.querySelector('[data-testid=next-week]');if(next)next.focus({preventScroll:true});modal('黑天鹅事件 · 已发生',`<section class="major-event-details" data-event-id="${esc(id)}"><h3>${esc(e.title)}</h3><p>发生于经营第 ${log.week} 周 · 当前经营第 ${s.week} 周</p><p>${esc(e.situation)}</p><small>以下为当前周实际成交价变化，包含随机波动与价格边界，不是配置首冲或新闻实测幅度。</small><div class="major-products">${Object.keys(e.effects).map(id=>swanQuote(s,id).replace(/data-action="trade"/g,'data-action="major-trade"')).join('')}</div><p>${e.duration>1?'持续影响只改变有效期内的价格中枢，不逐周重复首冲。':'一次性冲击只在发生周施加。'}到期不保证反弹或回到某个价位，之后仍可能涨跌。</p><section class="origin-facts"><h3>现实新闻原型 · 已核实事实</h3><p>${esc(o.name)} · ${esc(o.date)}</p><p>${esc(o.facts)}</p><a href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">${esc(o.agency)} · ${esc(o.title)}</a></section><section class="origin-adaptation"><h3>原创映射 · 并非现实价格结论</h3><p>${esc(o.adaptation)}</p><small>“黑天鹅”是游戏事件类别，现实原型并非都严格不可预期。本游戏使用虚构城市与原创事件，仅借鉴供需或预期机制，不构成投资或健康建议。</small></section>${btn('我知道了 / 返回市场','close','class="primary" data-testid="major-close"')}</section>`,'major-event');}
function rumorSource(sourceId){if(!Object.prototype.hasOwnProperty.call(H.hintSources,sourceId))return;modal('传闻来源 · 未核实',`<p>${esc(H.hintSources[sourceId])}只是街区闲谈，可能说错。</p><p>传闻指向下周参考成交价方向，不包含可能的退市回收折价和卖出手续费，不等于交易净收益。</p>`,'rumor-source');}
function rumorRows(s){return `<section class="rumor-section" data-testid="rumors"><h3>下周传闻${s.week<52&&s.status==='playing'?' · 第 '+(s.week+1)+' 周':''}</h3><small>仅供判断 · 可能错误 · 参考价方向不等于交易净收益</small>${s.rumors.map(r=>`<article class="rumor-line" data-rumor-product="${r.productId}"><strong>${esc(H.product(r.productId).name)} · 听说会${r.direction==='up'?'涨':'跌'}</strong><br>${btn(esc(H.hintSources[r.sourceId])+' ⓘ','rumor-source',`data-source-id="${r.sourceId}"`)}</article>`).join('')||`<p class="muted">${s.week>=52||s.status==='ended'?'本年没有下周传闻。':'这周暂无传闻。'}</p>`}</section>`;}
function bulletin(s){const line=n=>{if(!n)return '<p class="muted">这周没有新的市场头条。</p>';const p=n.productId?H.holding(n.productId):null,qty=p?H.qtyOf(s,p.id):0,listed=p&&!p.legacy&&s.listing.includes(p.id),net=qty?H.channelNet(s,p.id,qty):0,bps=p?H.changeBps(H.quoteOf(s,p.id)):0,ev=s.swanLog.some(l=>l.id===n.id)&&H.events.find(e=>e.id===n.id&&e.tier==='swan'),emphasis=ev&&n.kind==='headline'&&enteredByNext&&motion()&&!document.hidden;return `<article class="bulletin-line${ev?' swan-news':''}${emphasis?' swan-emphasis':''}" data-news-kind="${n.kind}"${ev?' data-major-event="'+ev.id+'"':''}${emphasis?' data-major-new="true"':''}>${ev?'<small class="major-label">重大事件 · '+(n.kind==='headline'?'本周已发生':'仍在影响')+'</small>':''}<strong>${esc(n.title)}</strong>${p&&n.kind!=='listing'?`<p class="${bps>=0?'up':'down'}" title="相对上周成交价">${esc(p.name)} · 本周 ${bps>=0?'+':''}${(bps/100).toFixed(1)}%</p>`:''}<p>${esc(!ev&&H.events.some(e=>e.id===n.id&&e.tier==='swan')?'':H.newsSituation(n))}</p>${p?`<small>${esc(p.name)} · ${listed?'本周可买':'仅可回收'} · 持有 ${qty} · 当前渠道净额 ${money(net)} · 浮盈 ${money(net-H.costOf(s,p.id))}</small>${btn('查看'+esc(p.name),'trade',`data-id="${p.id}" data-mode="${listed?'buy':'sell'}"`)}`:''}${ev?btn('现实原型 / 事件详情','major-event',`data-id="${ev.id}"`):''}${ev?Object.keys(ev.effects).filter(id=>id!==n.productId).map(id=>swanQuote(s,id)).join(''):''}</article>`;};return `<section class="panel bulletin" data-testid="bulletin"><div class="bulletin-head"><h3 id="bulletin-title" tabindex="-1">街区快报 · 第 ${s.week} 周</h3><small>市场景气：<b class="climate">${climateOf(s)}</b> · 消息不是保证</small></div><div class="bulletin-body scroll">${rumorRows(s)}<h3>本周事实 · 已发生</h3>${H.bulletinRows(s.news).map(line).join('')}<h3>仍在影响</h3>${s.news.filter(n=>n.kind==='ongoing').map(line).join('')||'<p class="muted">这周没有仍在持续的市场消息。</p>'}</div></section>`;}
function calendar(s){const cw=H.calendarWeek(s),remaining=13-((cw-1)%13),next=['冬','春','夏','秋'][(Math.floor((cw-1)/13)+1)%4],completed=s.status==='ended'?52:s.week-1;return `<section class="year-progress paper" data-testid="year-progress"><div class="year-progress-label"><strong>经营第 ${s.week} / 52 周</strong><small>${s.status==='ended'?'已结算':s.season+'季剩余 '+remaining+' 周（含本周） · 下一季：'+next+'季'}</small></div><div class="year-track" role="progressbar" aria-label="经营已完成周数" aria-valuemin="0" aria-valuemax="52" aria-valuenow="${completed}"><i style="width:${completed/52*100}%"></i></div>${s.status==='playing'&&s.week>=50?`<strong class="year-warning" data-testid="year-warning">含本周还可经营${53-s.week}周${s.week===52?' · 仍可交易，结束须确认':''}</strong>`:''}</section>`;}
function renderGame(){if(!engine)return;screen='game';const ui=resetWarehouse?{scroll:0,ids:[]}:captureWarehouse();resetWarehouse=false;const s=engine.snapshot(),{owned,goal,due,progress}=homeGoal(s),capacity=H.used(s),phase=phaseOf(s),season=SEASON[s.season],tone=(H.Art&&H.Art.phaseTone[phase])||'day',home=owned<0?'rent':'house-'+owned,climate=climateOf(s);app.innerHTML=`<section class="shell"><header class="topbar">${slot('street','street',{phase,season})}<div class="brand-chip paper">${H.Art?H.Art.icon('seal','seal'):''}<div><div class="brand">这一年，安个家</div><small>${s.status==='ended'?'已结算':'52 周经营 · 随机四季起步'}</small></div></div>${calendar(s)}<div class="metrics paper"><div class="metric"><small>可用现金</small><strong data-testid="cash">${money(s.cash)}</strong></div><div class="metric"><small tabindex="0" data-tip="账面净资产包含现金、参考市值、已购住房。参考市值未扣卖出费和回收折价，不能付房款。仓储投入不可回收。">净资产 ⓘ</small><strong>${money(H.assets(s))}</strong></div><div class="metric"><small>仓储容量</small><strong>${capacity} / ${s.capacity}</strong></div></div><div class="row top-actions">${btn('帮助','help')}${btn('设置','settings')}${btn('主页','home')}</div></header><nav class="mobile-nav" aria-label="游戏面板"><a href="#market-title">市场</a><a href="#warehouse-title">仓库</a><a href="#bulletin-title">快报</a></nav><div class="workspace"><aside class="left"><section class="panel window-panel"><div class="home-window" data-tone="${tone}">${slot('home',home,{phase,season})}</div><div class="window-caption"><small>我的窗口 · ${TONE_CN[tone]} · ${H.difficulty(s).name}</small><h3>${owned<0?'现在：租住的小房间':H.houses[owned].name}</h3></div><p class="musing">${s.week>44?'一年快过去了。再认真做一次决定。':s.cash>=due?'钥匙离你很近了。':s.week>20?'银行卡里的数字，开始有了故事。':'钱包不大，梦想倒是装得下。'}</p><small>下一站 · ${goal.name} · ${goal.district}</small><div class="progress key-progress"><i style="width:${progress*100}%"></i></div><p>现金还差 <strong>${money(Math.max(0,due-s.cash))}</strong></p>${btn('逛逛住房','houses','data-testid="houses"')}</section>${warehouse(s)}</aside><section class="panel market-panel">${s.upgrade?`<p class="migration-note" data-testid="upgrade-note">本周账目与行情保留，未来采用新事件规则，不沿旧规则。v3 备份 ${esc(s.upgrade.backup)}</p>`:''}${s.migration?`<p class="migration-note" data-testid="migration-note">这局从旧规则迁入。已退出商品的价格已冻结。未来不沿旧规则。备份 ${esc(s.migration.backup)}</p>`:''}${personalLetter(s)}<div class="awning" aria-hidden="true"></div><div class="row between market-head"><div><h2 id="market-title" tabindex="-1">街区市场</h2><small>看懂价格，也给风险留一点空间</small></div><small tabindex="0" data-tip="红色表示上涨，绿色表示下跌。曲线只展示最近12周，不预示未来。">最近 12 周行情 ⓘ</small></div><div class="tools"><small id="product-count"></small><select id="view-filter"><option value="all">全部商品</option><option value="held">我的持仓</option><option value="favorite">我的关注</option></select><select id="sort" data-testid="sort"><option value="focus" ${sort==='focus'?'selected':''}>本周关注</option><option value="default" ${sort==='default'?'selected':''}>街区顺序</option><option value="price" ${sort==='price'?'selected':''}>价格从低到高</option><option value="change" ${sort==='change'?'selected':''}>涨幅从高到低</option><option value="profit" ${sort==='profit'?'selected':''}>浮盈从高到低</option></select></div><div class="tabs">${['全部','生活','电子','贵重','季节','应急'].map(c=>btn(c,'category',`data-category="${c}" data-cat="${CAT[c]||'all'}" class="${filter===c?'active':''}"`)).join('')}</div><div id="market-list" class="market-list" data-testid="market-list"></div></section><aside class="right">${bulletin(s)}</aside></div><footer class="footer"><div><span class="status" data-testid="storage-status">${esc(storageStatus)}</span><br><small>空格下一周 · B 买 / S 卖 · Esc 返回</small></div>${btn(s.status==='ended'?'查看年度结算':s.week===52?'结束本年':'进入下一周 →',s.status==='ended'?'result':'next','class="primary" data-testid="next-week"')}<div class="footer-save">${btn('手动保存','save','data-testid="save"')}</div></footer></section>`;mountSlots(app);renderProducts();$('sort').value=sort;$('view-filter').value=viewFilter;restoreWarehouse(ui);syncScene();}
let viewFilter='all';
function renderProducts(){const s=engine.snapshot(),flash=enteredByNext&&motion();enteredByNext=false;const show=p=>{const listed=s.listing.includes(p.id),held=s.inventory[p.id].qty>0;if(viewFilter==='held')return held;if(viewFilter==='favorite'&&!favorites.has(p.id))return false;if(filter!=='全部'&&p.category!==filter)return false;return viewFilter!=='all'||listed;};let ps=H.products.filter(show);if(viewFilter==='held')ps=ps.concat(H.legacyProducts.filter(p=>s.legacy[p.id].qty));if(sort==='focus')ps=H.focusOrder(s,ps);else if(sort!=='default')ps.sort((a,b)=>sort==='price'?(a.legacy?s.legacy[a.id].price:s.market[a.id].price)-(b.legacy?s.legacy[b.id].price:s.market[b.id].price):sort==='change'?H.changeBps(b.legacy?s.legacy[b.id]:s.market[b.id])-H.changeBps(a.legacy?s.legacy[a.id]:s.market[a.id]):(H.channelNet(s,b.id,b.legacy?s.legacy[b.id].qty:s.inventory[b.id].qty)-(b.legacy?s.legacy[b.id].cost:s.inventory[b.id].cost))-(H.channelNet(s,a.id,a.legacy?s.legacy[a.id].qty:s.inventory[a.id].qty)-(a.legacy?s.legacy[a.id].cost:s.inventory[a.id].cost)));$('product-count').textContent='本周在售 '+s.listing.length+' 种 / 当前显示 '+ps.length+' 种';$('market-list').innerHTML=ps.map(p=>{const row=holdingRow(s,p.id),m=row.m,i=row.i,ch=H.changeBps(m)/100,headline=s.news.find(n=>n.kind==='headline'&&n.fresh),big=flash&&motion()&&!document.hidden&&headline&&headline.productId===p.id&&Math.abs(headline.changeBps)>=2500,profit=i.qty?H.channelNet(s,p.id,i.qty)-i.cost:0;return `<article class="product ${ch>=0?'rise':'fall'}${big?' surge':''}" data-cat="${CAT[p.category]}" data-action="trade" data-id="${p.id}" data-mode="${row.listed?'buy':'sell'}" data-testid="product-${p.id}" tabindex="0" role="button" aria-label="${p.name}详情和交易"><div class="product-head"><span class="shelf">${icon(p.id)}</span><div><h3>${p.name}</h3><small><i class="cat-tag">${p.category}</i> ${p.size}空间 / 件${row.listed?'':' · 未上架'}${row.legacy?' · 已退出':''}</small></div><button class="star" data-action="favorite" data-id="${p.id}" aria-label="${favorites.has(p.id)?'取消关注':'关注'}${p.name}" aria-pressed="${favorites.has(p.id)}">${favorites.has(p.id)?'★':'☆'}</button></div><div class="row between price-row"><strong>${money(m.price)}</strong><span class="${ch>=0?'up':'down'} change">${ch>=0?'+':''}${ch.toFixed(1)}%</span></div>${chart(m.history,'spark',{up:ch>=0})}<div class="product-footer"><span>持有 ${i.qty} (${i.qty*p.size}空间) · 均 ${i.qty?money(i.cost/i.qty):'—'}</span><span class="${profit>=0?'up':'down'}">浮盈 ${money(profit)}</span></div></article>`;}).join('')||'<p class="muted">没有匹配的商品。</p>'+btn('查看全部商品','reset-filter');}
function trade(id,mode='buy'){const scroll=dialog.open&&dialogKind==='trade'&&tradeId===id?dialog.querySelector('.dialog-body').scrollTop:0;const s0=engine.snapshot(),row0=holdingRow(s0,id),canBuy=row0.listed&&!row0.legacy;if(!canBuy)mode='sell';selected=id;tradeId=id;tradeMode=mode;const s=s0,row=row0,p=row.p,m=row.m,i=row.i,ch=H.changeBps(m)/100,profit=i.qty?H.channelNet(s,id,i.qty)-i.cost:0;modal(p.name+' · 商品与交易',`<div class="trade-layout"><section class="trade-chart"><div class="counter" data-cat="${CAT[p.category]}"><div class="trade-icon">${icon(id)}</div><div><small><i class="cat-tag">${p.category}</i> 单件占 ${p.size} 空间${row.listed?'':' · 未上架'}${row.legacy?' · 已退出市场':''}</small><h3>${money(m.price)} / 件</h3><span class="${ch>=0?'up':'down'}">较上周 ${ch>=0?'+':''}${ch.toFixed(1)}%</span></div></div><p>${p.description}</p>${chart(m.history,'spark trade-spark',{grid:true,avg:i.qty?i.cost/i.qty:0,up:ch>=0,label:'最近12周价格曲线'+(i.qty?'，虚线为持仓含费均价':'')+'，非未来预测'})}<small>最近12周${i.qty?' · <span class="avg-key">虚线</span> 持仓均价':''} · 上周 ${money(m.previous)}<br>历史 ${money(m.low)}—${money(m.high)}</small><p>公开参考价 ${money(p.basePrice)}<br>单件占 ${p.size} 空间</p><small>价格受季节、供需与市场环境影响，参考价不是保证。在售买卖各收1%手续费。未上架出售另计8%回收折价，手续费按回收报价另计。</small></section><section class="trade-form"><div class="tabs">${btn('买入','trade-mode',`data-mode="buy" data-testid="trade-buy" ${canBuy?'':'disabled'} class="${mode==='buy'?'active':''}"`)}${btn('卖出','trade-mode',`data-mode="sell" data-testid="trade-sell" class="${mode==='sell'?'active':''}"`)}</div><p>持仓 ${i.qty} · 均价 ${i.qty?money(i.cost/i.qty):'—'}<br>参考市值 ${money(i.qty*m.price)} · 按当前渠道卖出的浮盈 ${money(profit)}</p><label for="qty">整数数量</label><input id="qty" class="qty" data-testid="trade-qty" type="text" inputmode="numeric" value="1" autocomplete="off"><div class="choices">${[1,5].map(q=>btn(q+' 件','quantity',`data-qty="${q}"`)).join('')}${btn(mode==='buy'?'买最大':'卖全部','quantity','data-qty="max"')}</div><div id="preview" class="preview receipt" aria-live="polite"></div><p id="trade-reason" class="danger"></p>${btn(mode==='buy'?'确认买入':'确认卖出','submit-trade','class="primary" data-testid="trade-submit"')}<p><small>卡片和结算里的浮盈等于按当前渠道全部卖出的净回款减成本。参考市值未扣费，不能付房款。</small></p></section></div>`,'trade');preview();dialog.querySelector('.dialog-body').scrollTop=scroll;}
function preview(){if(!tradeId)return;const s=engine.snapshot(),row=holdingRow(s,tradeId),p=row.p,v=$('qty').value.trim(),qty=/^[1-9]\d*$/.test(v)?Number(v):0,valid=Number.isSafeInteger(qty)&&qty>0&&qty<=100000000,unit=tradeMode==='buy'?row.m.price:H.channelUnit(s,p.id),gross=valid?qty*unit:0,mark=valid?qty*row.m.price:0,discount=tradeMode==='sell'?mark-gross:0,fee=valid?H.fee(gross):0,cash=s.cash+(tradeMode==='buy'?-gross-fee:gross-fee),space=H.used(s)+(tradeMode==='buy'?1:-1)*qty*p.size;let reason=!valid?'请输入有效的正整数数量（不能含小数、负号或科学记数）':s.status==='ended'?'本年已结束':tradeMode==='buy'&&row.legacy?'已退出市场，只能按冻结回收价出售':tradeMode==='buy'&&!row.listed?'本周未上架':tradeMode==='buy'&&qty>maxBuy(s,p)?(space>s.capacity?'仓储空间不足，请减少数量或升级仓储':'资金不足，含手续费的支出超过现金'):tradeMode==='sell'&&qty>row.i.qty?'持仓不足':'';$('preview').innerHTML=`<div class="receipt-head"><b>街区小票</b><small>第 ${s.week} 周 · ${tradeMode==='buy'?'买入':'卖出'} ${esc(p.name)} × ${valid?qty:'—'}</small></div><dl><dt>${tradeMode==='sell'&&unit!==row.m.price?'回收报价':'货款'}</dt><dd>${money(gross)}</dd>${discount?`<dt>回收折价</dt><dd>${money(discount)}</dd>`:''}<dt>手续费</dt><dd>${money(fee)}</dd><dt class="total">${tradeMode==='buy'?'总支出':'净回款'}</dt><dd class="total">${money(tradeMode==='buy'?gross+fee:gross-fee)}</dd><dt>交易后现金</dt><dd>${money(cash)}</dd><dt>仓储</dt><dd>${space} / ${s.capacity} · 可买 ${maxBuy(s,p)}</dd></dl>`;$('trade-reason').textContent=reason;dialog.querySelector('[data-action=submit-trade]').disabled=!!reason;}
function houses(){const s=engine.snapshot(),old=H.houses.findIndex(h=>h.id===s.house),season=SEASON[s.season],phase=phaseOf(s);modal('一扇属于自己的门',`<p>升级全额抵扣旧房购买价。买房不结束本年，仍可继续经营。</p><div class="house-grid flyers">${H.houses.map((h,j)=>{const price=H.housePrice(s,h),due=price-H.houseValue(s),reason=s.status==='ended'?'本年已结束':j<=old?(j===old?'已拥有':'不可降档'):s.cash<due?'现金还差 '+money(due-s.cash):'';return `<article class="house-card flyer${j===old?' owned':''}${j<old?' passed':''}"><div class="flyer-art">${scene('house-'+j,{phase,season})}<span class="district-tag">${h.district}</span>${j===old?'<span class="owned-stamp" aria-hidden="true">已入住</span>':''}</div><div class="flyer-body"><h3>${h.name} · ${h.district}</h3><p>${h.description}</p><div class="flyer-price"><strong>${money(price)}</strong><small> · ${h.ending}</small></div><p>抵扣 ${money(H.houseValue(s))} · 应付 ${money(Math.max(0,due))}</p><div class="progress key-progress"><i style="width:${due>0?Math.min(100,s.cash/due*100):100}%"></i></div>${btn(reason||'拿到这把钥匙','buy-house',`data-id="${h.id}" ${reason?'disabled':''} data-testid="house-${h.id}"`)}${reason?'<small>'+reason+'</small>':''}</div></article>`;}).join('')}</div>`,'houses');}
function warehouses(){const s=engine.snapshot(),old=H.warehouses.findIndex(w=>w.id===s.warehouse),spent=H.warehousePrice(s,H.warehouses[old]);modal('给生意留一点空间',`<div class="warehouse-art">${scene('warehouse',{phase:phaseOf(s),season:SEASON[s.season]})}</div><p class="danger">仓储是租赁投入，不返还、不计入净资产；升级支付累计投入差额，不能降级。</p><div class="house-grid">${H.warehouses.map((w,j)=>{const price=H.warehousePrice(s,w),due=price-spent,reason=s.status==='ended'?'本年已结束':j<=old?(j===old?'当前仓储':'不可降级'):s.cash<due?'现金不足':'';return `<article class="house-card crate${j===old?' owned':''}"><h3>${w.name}</h3><p>容量 ${w.capacity} · 累计 ${money(price)}</p><p>本次差价 ${money(Math.max(0,due))}</p>${btn(reason||'升级仓储','buy-warehouse',`data-id="${w.id}" ${reason?'disabled':''} data-testid="warehouse-${w.id}"`)}</article>`;}).join('')}</div>`,'warehouses');}
function help(){modal('经营手册',`<div class="stack"><section><h3>先活下来，再买一扇门</h3><p>经营时间仍为52周，新局从随机日历周开始，冬春夏秋各13周循环。进度条表示已完成经营周数，本季剩余含本周。最后3/2/1周会提醒；第52周仍可交易，结束须确认。52周内买下正式住房。留现金应对生活支出，不要把全部资金押在单个高波动商品上。低于参考价不是必涨；季节需求也可能被供给变化抵消。</p></section><section><h3>交易与费用</h3><p>每周8种在售可买。未上架和已退出市场的持仓仍可卖。在售买卖各1%，按分向上取整。未上架出售先按8%折成回收报价，手续费再按报价另计。买入费用计入持仓成本；部分卖出按比例分摊成本，清仓带走余数。浮盈等于按当前渠道全部卖出的净回款减成本。账面净资产里的参考市值不能付房款。住房升档抵扣本局价格簿里的旧价；仓储费用不可回收。</p></section><section><h3>消息与行情</h3><p>快报里的百分比来自本周成交价。没有新事件时，明显涨跌只说明已经发生，不编造原因。下周传闻是未核实的街区闲谈，可能错误，只谈下周参考成交价方向；它不含可能的退市回收折价与卖出费，不等于交易净收益。个人事件只影响生活收支，不改变商品价格。</p></section><section><h3>操作与快捷键</h3><p>点击商品查看指南和交易，☆关注。左侧我的仓库可直接卖1、卖5或卖全部，也可展开自定义数量。分类、持仓/关注筛选与五种排序可组合。右侧快报区分本周摘要与仍在影响，轮换行不附总涨跌。Space进入下一周，1—9选择前九种商品，B买入、S卖出，Esc关闭窗口。输入和局部按钮接管空格时不推进；按钮的Space/Enter只激活该按钮，长按不重复成交或推进。第52周可交易，结束本年前须确认。</p></section>${btn('重新观看四步引导','tutorial','class="primary"')}<small>声音仅在用户交互后启动，可随时在设置关闭。关闭自动存档后请手动保存或导出。</small></div>`,'help');}
let tourStep=0;const tours=[['钱包和时间','你有52周。现金用于交易与生活支出；净资产还包含库存和房屋，不能直接拿库存去买房。'],['看一看街区市场','点击商品，查看12周行情、参考价和体积。先小额买入，保留现金，别把低价当成保证。'],['卖出与空间','在左侧我的仓库直接卖1、卖5或卖全部；不足5件时卖5禁用。自定义数量在卡片内确认，详情仍可看曲线。手续费买卖各1%；仓储投入不可返还。'],['把门钥匙握在手里','现金达到目标后去逛住房。旧房全额抵扣可升级。第52周结束本年，别忘了实际买房。']];function tutorial(){modal('新生活指南 '+(tourStep+1)+' / 4',`<h3>${tours[tourStep][0]}</h3><p>${tours[tourStep][1]}</p><div class="row">${btn('跳过引导','tour-finish')}${btn(tourStep===3?'开始经营':'下一步','tour-next','class="primary" data-testid="tour-next"')}</div>`,'tutorial');}
function settingsView(){modal('设置与存档',`<div class="stack"><section><label class="settings-row" for="audio-volume">音量 <output id="audio-volume-percent" for="audio-volume">${Math.round(H.Audio.volume()*100)}%</output><input id="audio-volume" data-testid="audio-volume" type="range" min="0" max="100" step="1" value="${Math.round(H.Audio.volume()*100)}"></label>${[['sound','音效'],['music','原创暖调音乐'],['autoSave','自动存档']].map(([k,t])=>`<label class="settings-row">${t}<input type="checkbox" data-setting="${k}" ${settings[k]?'checked':''}></label>`).join('')}<label class="settings-row">动画强度<select data-setting="animation">${[['normal','正常'],['reduced','减少'],['off','关闭']].map(([v,t])=>`<option value="${v}" ${settings.animation===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="settings-row">数字格式<select data-setting="numberFormat"><option value="decimal" ${settings.numberFormat==='decimal'?'selected':''}>完整金额</option><option value="compact" ${settings.numberFormat==='compact'?'selected':''}>大金额以万显示</option></select></label></section><section><h3>本地存档</h3><p data-testid="save-status">${esc(storageStatus)}</p><div class="row">${btn('手动保存','save',!engine?'disabled':'')}${btn('导出当前游戏','export',!engine?'disabled':'')}${btn('导出损坏原文','damaged',saves.damaged()===null?'disabled':'')}${btn('导出旧档原文','export-legacy',saves.oldRaw()?'':'disabled')}${btn('导出 v2 原键','export-v2',saves.legacyRaw()?'':'disabled')}${engine&&(engine.snapshot().migration||engine.snapshot().upgrade)?btn('导出升级/迁移备份','export-backup','data-testid="export-backup"'):''}${engine&&engine.snapshot().upgrade&&engine.snapshot().migration?btn('导出原 v2 备份','export-v2-backup'):''}</div><div class="row">${btn('明确覆盖隔离档','replace',!engine||!saves.isQuarantined()?'disabled':'')}${btn('删除本地存档','delete','class="danger"')}</div><p><small>file://存储由浏览器隔离，导出JSON是当前版本的可移植备份。内测规则更新，旧档不兼容，请开始新游戏。导入成功只替换内存，不立刻覆盖存档。</small></p><label>选择存档文件 <input id="import-file" type="file" accept=".json,.txt"></label><textarea id="save-text" data-testid="save-text" placeholder="也可粘贴完整JSON"></textarea>${btn('校验并导入','import','data-testid="import"')}</section>${btn('放弃本局，重新开始','restart','class="danger"')}</div>`,'settings');}
function result(){const s=engine.snapshot(),r=H.summary(s),idx=H.houses.findIndex(h=>h.id===s.house),home=idx>=0,phase=home?'ending-home':'ending-rent',assets=r.history.map(p=>p.assets),peakI=assets.indexOf(Math.max(...assets)),marks=[{type:'dot',i:peakI,color:'#b88a4a'}],stats=[['最终资产',r.assets],['最终现金',r.cash],['参考市值',r.inventoryValue],['按当前渠道可卖净额',r.liquidValue],['累计交易额',r.turnover],['已实现收益',r.profit],['按当前渠道卖出的浮盈',r.unrealized],['总手续费',r.fees],['最高资产',r.peak],['最大单笔盈利',r.best],['最大单笔亏损',r.worst],['生活收入',s.stats.grants],['生活支出',s.stats.expenses],['未付困难',s.stats.hardship],['仓储投入',s.stats.warehouseSpent]];if(r.houseWeek)marks.unshift({type:'line',i:Math.min(assets.length-1,r.houseWeek-1),color:'#c95a48'});modal('这一年的故事',`<div class="storybook ${home?'book-home':'book-rent'}"><section class="page page-left"><div class="result-hero">${scene(home?'house-'+idx:'rent',{phase,season:SEASON[s.season]})}<h2>${r.ending}</h2><p>${!home?'房间还是熟悉的出租屋，但你已学会和市场打交道。窗里那盏灯，还亮着。':'从今天起，推开的是自己家的门。'}</p><small>${!home?'仍在租房':H.houses[idx].name} · Seed ${esc(s.seed)} · ${H.difficulty(s).name}</small></div></section><section class="page page-right ledger"><h3>这一年的账本</h3>${chart(assets,'asset-chart',{grid:true,marks,label:'每周资产曲线'+(r.houseWeek?'，红色虚线为首次购房周':'')+'，金色点为资产峰值'})}<small>每周资产曲线 · 库存按末周市值计，不强制清仓${r.houseWeek?` · <span class="mark-house">┊</span> 第 ${r.houseWeek} 周首次购房`:''} · <span class="mark-peak">●</span> 第 ${peakI+1} 周资产峰值</small><div class="stats-grid">${stats.map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${money(v)}</strong></div>`).join('')}<div class="stat-box"><small>交易次数 / 最大回撤</small><strong>${r.trades} / ${(r.maxDrawdown/10000).toFixed(1)}%</strong></div><div class="stat-box"><small>首次购房 / 升级仓储</small><strong>${r.houseWeek||'—'} 周 / ${r.upgrades} 次</strong></div></div><p>最好收益：${H.holding(r.bestProduct).name} ${money(r.byProduct[r.bestProduct])}<br>最差收益：${H.holding(r.worstProduct).name} ${money(r.byProduct[r.worstProduct])}</p><details><summary>全部商品收益</summary>${H.heldProducts().map(p=>`<div class="inventory-line"><span>${p.name}</span><span>${money(r.byProduct[p.id])}</span></div>`).join('')}</details><div class="row">${btn('导出这一年','export')}${btn('再过一个新年','restart','class="primary" data-testid="restart"')}</div></section></div>`,'result');}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function newGame(){const seed=$('seed').value.trim(),difficulty=$('difficulty').value;const create=()=>{try{engine=new H.Engine(seed,difficulty);wire();clearWarehouseUI();if(settings.autoSave){const r=saves.save(engine.snapshot());storageStatus=r.ok?'新的一年已保存':'未保存：'+r.error;}close();enteredByNext=false;renderGame();let seen=false;try{seen=localStorage.getItem('homeyear.tutorial')==='seen';}catch(e){}if(!seen){tourStep=0;tutorial();}}catch(e){toast(e.message,true);}};if(load.state||saves.isQuarantined()||engine)confirmBox('新局将替换当前内存进度，并在自动存档开启时覆盖有效本地存档。隔离原档不会自动覆盖。确认开始？',create);else create();}
const actions={'rumor-source':e=>rumorSource(e.dataset.sourceId),'major-event':e=>majorEvent(e.dataset.id),'major-trade'(e){const id=e.dataset.id,mode=e.dataset.mode;close();trade(id,mode);},'reset-filter'(){filter='全部';viewFilter='all';renderGame();},'quick-sell'(el){const s=engine.snapshot(),q=el.dataset.qty==='all'?H.qtyOf(s,el.dataset.id):Number(el.dataset.qty);submitSale(el,el.dataset.id,q);},'custom-sell'(el){const id=el.dataset.id;warehouseDrafts.has(id)?warehouseDrafts.delete(id):warehouseDrafts.set(id,'1');renderGame();},'custom-submit'(el){const v=salePreview(engine.snapshot(),el.dataset.id,warehouseDrafts.get(el.dataset.id)||'');if(v.reason){toast(v.reason,true);return;}submitSale(el,el.dataset.id,v.q);},'audio-enable':audioCheck,close,confirm(){const fn=confirmFn;confirmFn=null;close();if(fn)fn();},new:newGame,continue(){load=saves.load();if(load.ok&&load.state){engine=new H.Engine(load.state.seed,load.state.difficulty);engine.restore(load.state);wire();clearWarehouseUI();enteredByNext=false;renderGame();if(load.state.status==='ended')result();}else{toast(load.error||'暂无可继续存档',true);start();}},home(){close();load=saves.load();start();},help,settings:settingsView,houses,warehouses,result,trade:e=>trade(e.dataset.id,e.dataset.mode||(e.dataset.id&&engine&&!engine.snapshot().listing.includes(e.dataset.id)?'sell':'buy')),favorite(e){const id=e.dataset.id;favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('homeyear.favorites',JSON.stringify([...favorites]));}catch(err){}renderProducts();},category(e){filter=e.dataset.category;renderGame();},'trade-mode':e=>trade(tradeId,e.dataset.mode),quantity(e){const s=engine.snapshot(),row=holdingRow(s,tradeId);$('qty').value=e.dataset.qty==='max'?(tradeMode==='buy'?maxBuy(s,row.p):row.i.qty):e.dataset.qty;preview();},migrate(el){const read=saves.readKey(el&&el.dataset.oldVersion==='2'?saves.legacyKey:oldKey());if(!read.ok){toast(read.error,true);return;}if(!read.raw){toast('没有可迁移的旧档',true);return;}confirmBox(oldConfirm(JSON.parse(read.raw).version),()=>{const go=replaceDamaged=>{const r=saves.migrate(read.raw,{replaceDamaged:replaceDamaged===true});if(!r.ok){toast(r.error,true);return;}load=saves.load();engine=new H.Engine(r.state.seed,r.state.difficulty);engine.restore(r.state);wire();clearWarehouseUI();enteredByNext=false;renderGame();if(r.state.status==='ended')result();toast('已迁入。原旧档仍留在原来的键里。');};if(saves.isQuarantined())confirmBox(H.replaceDamagedConfirm,()=>go(true));else go(false);});},'submit-trade'(){const id=tradeId,mode=tradeMode,q=Number($('qty').value);if(act(mode,id,q))trade(id,mode);},'buy-house'(e){const id=e.dataset.id;confirmBox('确认购入 / 升级住房？旧房全额抵扣，购买后仍可继续本年。',()=>{if(act('house',id))houses();});},'buy-warehouse'(e){const id=e.dataset.id;confirmBox('仓储投入不可返还、不计资产。确认升级？',()=>{if(act('warehouse',id))warehouses();});},next(){if(engine.snapshot().week===52)confirmBox('结束本年后不能再交易或购房。库存按当前市值计，不自动出售。确定结算？',()=>act('end'));else act('next');},save(){if(!engine)return;const r=saves.save(engine.snapshot());storageStatus=r.ok?'已手动保存':'未保存：'+r.error;toast(storageStatus,!r.ok);if(dialog.open)settingsView();else renderGame();},export(){if(engine)download(saves.export(engine.snapshot()),'homeyear-'+engine.visible().seed+'.json');},damaged(){if(saves.damaged()!==null)download(saves.damaged(),'homeyear-damaged.txt');},'export-v2'(){const r=saves.readKey(saves.legacyKey);if(r.ok&&typeof r.raw==='string')download(r.raw,'homeyear-v2-original.json');else toast(r.error||'没有 v2 原文',true);},'export-v2-backup'(){const ref=engine&&engine.snapshot().migration,r=ref&&saves.readKey(ref.backup);if(r&&r.ok&&typeof r.raw==='string')download(r.raw,'homeyear-v2-backup.json');else toast('没有可读取的 v2 备份',true);},'export-legacy'(){const r=saves.readKey(oldKey());if(!r.ok||typeof r.raw!=='string'){toast(r.error||'没有可导出的原文',true);return;}download(r.raw,'homeyear-old-original.json');},'export-backup'(){if(!engine||!(engine.snapshot().upgrade||engine.snapshot().migration)){toast('这局没有迁移备份',true);return;}const state=engine.snapshot(),ref=state.upgrade||state.migration;const r=saves.readKey(ref.backup);if(!r.ok||typeof r.raw!=='string'){toast(r.error||'没有可导出的原文',true);return;}download(r.raw,'homeyear-migration-backup.json');},replace(){confirmBox('请先导出损坏原文。明确用当前游戏覆盖隔离的原档？',()=>{const r=saves.save(engine.snapshot(),{replaceDamaged:true});storageStatus=r.ok?'已明确覆盖原档':r.error;toast(storageStatus,!r.ok);settingsView();});},delete(){confirmBox('只删除本地存档，当前游戏仍保留；之后的自动保存会重新创建。确认删除？',()=>{const r=saves.remove();storageStatus=r.ok?'存档已删除':r.error;load=saves.load();toast(storageStatus,!r.ok);settingsView();});},import(){const raw=$('save-text').value,v3=saves.parse(raw);if(v3.ok){confirmBox('替换当前内存游戏？不会立即覆盖本地档。',()=>{if(!engine)engine=new H.Engine(v3.state.seed,v3.state.difficulty);const v=saves.import(raw,engine);if(v.ok){wire();clearWarehouseUI();enteredByNext=false;storageStatus='导入成功 · 尚未覆盖本地存档';renderGame();if(v3.state.status==='ended')result();}toast(v.ok?storageStatus:v.error,!v.ok);});return;}toast('导入失败，内存未改变：'+v3.error,true);},restart(){confirmBox('离开当前进度并返回新局页面？未保存进度会丢失。',()=>{engine=null;load=saves.load();start();});},tutorial(){tourStep=0;tutorial();},'tour-next'(){if(tourStep<3){tourStep++;tutorial();}else actions['tour-finish']();},'tour-finish'(){try{localStorage.setItem('homeyear.tutorial','seen');}catch(e){}close();}};
let activationKey=null;
document.addEventListener('keyup',e=>{if(activationKey&&activationKey.key===e.key)setTimeout(()=>{activationKey=null;},0);});
window.addEventListener('blur',()=>{activationKey=null;});
document.addEventListener('click',e=>{if(e.detail===0&&activationKey){if(activationKey.used)return;activationKey.used=true;}H.Audio.unlock();if($('audio-enable'))audioCheck();const el=e.target.closest('[data-action]');if(!el||el.disabled||e.detail>1)return;const fn=actions[el.dataset.action];if(fn)fn(el);});
// Touch screens do not have hover or a useful context menu. Pointer down is used only for
// gesture-scoped audio unlock and to dismiss stale tooltips before the synthesized click.
document.addEventListener('pointerdown',e=>{if(!e.isPrimary)return;H.Audio.unlock();$('tooltip').hidden=true;});
document.addEventListener('contextmenu',e=>{if(e.target.closest('[data-action],.product'))e.preventDefault();});
document.addEventListener('input',e=>{if(e.target.id==='audio-volume'){H.Audio.unlock();H.Audio.setVolume(Number(e.target.value)/100);$('audio-volume-percent').textContent=e.target.value+'%';}if(e.target.id==='qty')preview();if(e.target.dataset.saleInput){const id=e.target.dataset.saleInput;warehouseDrafts.set(id,e.target.value);const v=salePreview(engine.snapshot(),id,e.target.value);document.querySelector(`[data-custom-preview="${id}"]`).innerHTML=saleText(v);document.querySelector(`[data-action=custom-submit][data-id="${id}"]`).disabled=!!v.reason;}});
// Settings changes resume audio inside the same trusted change event (fixes music enabled without a running context).
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='sort'){sort=el.value;renderProducts();}if(el.id==='view-filter'){viewFilter=el.value;renderProducts();}if(el.dataset.setting){settings[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value;const r=saves.saveSettings(settings);applySettings();if(e.isTrusted&&(settings.music||settings.sound))H.Audio.unlock();if(!r.ok)toast(r.error,true);if(engine)renderGame();}if(el.id==='import-file'&&el.files[0]){const f=el.files[0];if(f.size>2000000){toast('文件过大',true);return;}try{$('save-text').value=await f.text();}catch(err){toast(err.message,true);}}});
dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
document.addEventListener('keydown',e=>{if(e.isTrusted&&(e.key==='Enter'||e.key===' ')&&!e.repeat)activationKey={key:e.key,used:false};if(e.isTrusted)H.Audio.unlock();if(dialog.open&&e.key==='Tab'){e.preventDefault();const items=[...dialog.querySelectorAll('button,input,select,textarea,a[href],[tabindex],[contenteditable="true"]')].filter(el=>!el.matches(':disabled')&&el.tabIndex>=0&&!el.closest('[hidden],[inert]')&&el.getClientRects().length&&getComputedStyle(el).visibility==='visible');if(!items.length){dialog.tabIndex=-1;dialog.focus();}else{const i=items.indexOf(document.activeElement);items[i<0?(e.shiftKey?items.length-1:0):(i+(e.shiftKey?-1:1)+items.length)%items.length].focus();}return;}if(e.repeat){if(e.key==='Enter'||e.key===' ')e.preventDefault();return;}if(e.key==='Escape'){if(dialog.open)close();return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('product')){e.preventDefault();trade(e.target.dataset.id);return;}if(!engine||screen!=='game')return;if(dialog.open)return;if((e.key===' '||e.key==='Enter')&&e.target.closest('button,a[href],summary,[role=button]'))return;if(e.code==='Space'){e.preventDefault();actions.next();}else if(/^[1-9]$/.test(e.key)){const card=[...document.querySelectorAll('#market-list [data-testid^=product-]')][Number(e.key)-1];if(card)trade(card.dataset.id,card.dataset.mode||'buy');}else if(e.key.toLowerCase()==='b')trade(selected,'buy');else if(e.key.toLowerCase()==='s')trade(selected,'sell');});
document.addEventListener('focusin',e=>{const el=e.target.closest('[data-action=quick-sell]');if(!el||!engine)return;const s=engine.snapshot(),q=el.dataset.qty==='all'?H.qtyOf(s,el.dataset.id):Number(el.dataset.qty),box=document.querySelector(`[data-quick-preview="${el.dataset.id}"]`);if(box)box.innerHTML=saleText(salePreview(s,el.dataset.id,String(q)));});
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const el=e.target.closest('[data-tip]');if(!el)return;const t=$('tooltip'),r=el.getBoundingClientRect();t.textContent=el.dataset.tip;t.hidden=false;t.style.left=Math.min(innerWidth-280,r.left)+'px';t.style.top=(r.bottom+8)+'px';});document.addEventListener('pointerout',e=>{if(e.pointerType==='touch')return;if(e.target.closest('[data-tip]'))$('tooltip').hidden=true;});document.addEventListener('focusin',e=>{const el=e.target.closest('[data-tip]');if(el){const r=el.getBoundingClientRect(),t=$('tooltip');t.textContent=el.dataset.tip;t.hidden=false;t.style.left=Math.min(innerWidth-280,r.left)+'px';t.style.top=(r.bottom+8)+'px';}});document.addEventListener('focusout',()=>{$('tooltip').hidden=true;});
// Read-only additions for automation: phase(), audioScene(), fx(), sceneBuilds(). Existing members unchanged.
H.UI={snapshot:()=>engine?engine.snapshot():null,screen:()=>screen,settings:()=>({...settings}),audioVolume:()=>H.Audio.volume(),openHelp:help,openSettings:settingsView,phase:()=>document.body.dataset.phase,audioScene:()=>lastScene?{...lastScene}:null,fx:()=>({celebrating:fx.celebrating,confetti:fx.confetti,rafActive:!!fx.raf,frames:fx.frames}),sceneBuilds:()=>Object.fromEntries([...slots].map(([k,v])=>[k,v.built]))};applySettings();start();if(!sr.ok)toast('设置读取失败，已使用默认设置：'+sr.error,true);
})(window.HomeYear);
